INSERT INTO publish_attempt (
    attempt_id, post_id, creator_id, idempotent_key, status, run_version,
    failed_step, error_message, content_object_key_snapshot, content_etag_snapshot,
    content_sha256_snapshot, retry_count, created_at, updated_at
) VALUES (
    #{attemptId}, #{postId}, #{creatorId}, #{idempotentKey}, #{status}, #{runVersion},
    #{failedStep}, #{errorMessage}, #{contentObjectKeySnapshot}, #{contentEtagSnapshot},
    #{contentSha256Snapshot}, #{retryCount}, #{createdAt}, #{updatedAt}
)

mapper.select:
SELECT *
FROM publish_attempt
WHERE creator_id = #{creatorId}
  AND post_id = #{postId}
  AND idempotent_key = #{idempotentKey}
LIMIT 1

mapper.update:
UPDATE publish_attempt
SET status = 'succeeded',
    failed_step = NULL,
    error_message = NULL,
    updated_at = #{publishedAt}
WHERE attempt_id = #{attemptId}
  AND run_version = #{runVersion}
  AND status = 'publishing'
